WITH deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY status, customer_id ORDER BY start_date NULLS FIRST, id) AS latest_rank FROM subscriptions QUALIFY latest_rank = 1) SELECT status, DATE_TRUNC('WEEK', end_date) AS week_start, MAX(monthly_fee) FILTER (WHERE plan = 'enterprise') AS enterprise_max_monthly_fee, STDDEV_SAMP(monthly_fee) AS monthly_fee_stddev, COUNT(CASE WHEN plan = 'standard' THEN 1 END) AS standard_count, RANK() OVER (PARTITION BY status ORDER BY COUNT(CASE WHEN plan = 'standard' THEN 1 END) DESC) AS standard_count_rank FROM deduped GROUP BY status, DATE_TRUNC('WEEK', end_date) ORDER BY monthly_fee_stddev NULLS FIRST
